/** Source: pokedex.c → Task_HandlePokedexStartMenuInput */
export const Task_HandlePokedexStartMenuInput: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  rt.SetGpuReg(REG_OFFSET_BG0VOFS, sPokedexView.menuY);

       
      if (sPokedexView.menuY != 80)
      {
          sPokedexView.menuY += 8;
      }
      else
      {
          if (JOY_NEW(A_BUTTON))
          {
              switch (sPokedexView.menuCursorPos)
              {
              case 0:  
              default:
                  gMain.newKeys |= START_BUTTON;   
                  break;
              case 1:  
                  sPokedexView.selectedPokemon = 0;
                  sPokedexView.pokeBallRotation = POKEBALL_ROTATION_TOP;
                  ClearMonSprites();
                  CreateMonSpritesAtPos(sPokedexView.selectedPokemon, 0xE);
                  gMain.newKeys |= START_BUTTON;   
                  break;
              case 2:  
                  sPokedexView.selectedPokemon = sPokedexView.pokemonListCount - 1;
                  sPokedexView.pokeBallRotation = sPokedexView.pokemonListCount * 16 + POKEBALL_ROTATION_BOTTOM;
                  ClearMonSprites();
                  CreateMonSpritesAtPos(sPokedexView.selectedPokemon, 0xE);
                  gMain.newKeys |= START_BUTTON;   
                  break;
              case 3:  
                  rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 0x10, "RGB_BLACK");
                  task.func = (t) => Task_ClosePokedex(t, rt);
                  /* TODO sound PlaySE */;
                  break;
              }
          }

           
          if (JOY_NEW(START_BUTTON | B_BUTTON))
          {
              sPokedexView.menuIsOpen = false;
              task.func = (t) => Task_HandlePokedexInput(t, rt);
              /* TODO sound PlaySE */;
          }
          else if (JOY_REPEAT(DPAD_UP) && sPokedexView.menuCursorPos != 0)
          {
              sPokedexView.menuCursorPos--;
              /* TODO sound PlaySE */;
          }
          else if (JOY_REPEAT(DPAD_DOWN) && sPokedexView.menuCursorPos < 3)
          {
              sPokedexView.menuCursorPos++;
              /* TODO sound PlaySE */;
          }
      }
};

