/** Source: pokedex.c → Task_LoadCryScreen */
export const Task_LoadCryScreen: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (gMain.state)
      {
      case 0:
      default:
          if (!rt.gPaletteFade.active)
          {
              m4aMPlayStop(gMPlayInfo_BGM);
              sPokedexView.currentPage = PAGE_CRY;
              gPokedexVBlankCB = gMain.vblankCallback;
              /* noop SetVBlankCallback */;
              ResetOtherVideoRegisters(DISPCNT_BG1_ON);
              sPokedexView.selectedScreen = CRY_SCREEN;
              gMain.state = 1;
          }
          break;
      case 1:
          DecompressAndLoadBgGfxUsingHeap(3, gPokedexMenu_Gfx, 0x2000, 0, 0);
          CopyToBgTilemapBuffer(3, gPokedexCryScreen_Tilemap, 0, 0);
          FillWindowPixelBuffer(WIN_INFO, PIXEL_FILL(0));
          PutWindowTilemap(WIN_INFO);
          PutWindowTilemap(WIN_VU_METER);
          PutWindowTilemap(WIN_CRY_WAVE);
          gMain.state++;
          break;
      case 2:
          LoadScreenSelectBarSubmenu(0xD);
          HighlightSubmenuScreenSelectBarItem(1, 0xD);
          LoadPokedexBgPalette(sPokedexView.isSearchResults);
          gMain.state++;
          break;
      case 3:
          ResetPaletteFade();
          gMain.state++;
          break;
      case 4:
          PrintInfoScreenText(gText_CryOf, 82, 33);
          PrintCryScreenSpeciesName(0, sPokedexListItem.dexNum, 82, 49);
          gMain.state++;
          break;
      case 5:
          task.data[3] = CreateMonSpriteFromNationalDexNumber(sPokedexListItem.dexNum, MON_PAGE_X, MON_PAGE_Y, 0);
          rt.gba.oam[_gs(rt, task.data[3]).oamIndex].priority = 0;
          gDexCryScreenState = 0;
          gMain.state++;
          break;
      case 6:
          {
              let waveformWindow: any = null;

              waveformWindow.unk0 = 0x4020;
              waveformWindow.unk2 = 31;
              waveformWindow.paletteNo = 8;
              waveformWindow.yPos = 30;
              waveformWindow.xPos = 12;
              if (LoadCryWaveformWindow(waveformWindow, 2))
              {
                  gMain.state++;
                  gDexCryScreenState = 0;
              }
          }
          break;
      case 7:
          {
              let cryMeter: any = null;

              cryMeter.paletteNo = 9;
              cryMeter.xPos = 18;
              cryMeter.yPos = 3;
              if (LoadCryMeter(cryMeter, 3))
                  gMain.state++;
              CopyWindowToVram(WIN_VU_METER, COPYWIN_GFX);
              CopyWindowToVram(WIN_INFO, COPYWIN_FULL);
              CopyBgTilemapBufferToVram(0);
              CopyBgTilemapBufferToVram(1);
              CopyBgTilemapBufferToVram(2);
              CopyBgTilemapBufferToVram(3);
          }
          break;
      case 8:
          rt.BeginNormalPaletteFade("PALETTES_ALL & ~(0x14)", 0, 0x10, 0, "RGB_BLACK");
          /* noop SetVBlankCallback */;
          gMain.state++;
          break;
      case 9:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          ShowBg(0);
          ShowBg(1);
          ShowBg(2);
          ShowBg(3);
          gMain.state++;
          break;
      case 10:
          sPokedexView.screenSwitchState = 0;
          gMain.state = 0;
          task.func = (t) => Task_HandleCryScreenInput(t, rt);
          break;
      }
};

