/** Source: pokedex.c → Task_LoadSizeScreen */
export const Task_LoadSizeScreen: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let spriteId = 0;

      switch (gMain.state)
      {
      default:
      case 0:
          if (!rt.gPaletteFade.active)
          {
              sPokedexView.currentPage = PAGE_SIZE;
              gPokedexVBlankCB = gMain.vblankCallback;
              /* noop SetVBlankCallback */;
              ResetOtherVideoRegisters(DISPCNT_BG1_ON);
              sPokedexView.selectedScreen = SIZE_SCREEN;
              gMain.state = 1;
          }
          break;
      case 1:
          DecompressAndLoadBgGfxUsingHeap(3, gPokedexMenu_Gfx, 0x2000, 0, 0);
          CopyToBgTilemapBuffer(3, gPokedexSizeScreen_Tilemap, 0, 0);
          FillWindowPixelBuffer(WIN_INFO, PIXEL_FILL(0));
          PutWindowTilemap(WIN_INFO);
          gMain.state++;
          break;
      case 2:
          LoadScreenSelectBarSubmenu(0xD);
          HighlightSubmenuScreenSelectBarItem(2, 0xD);
          LoadPokedexBgPalette(sPokedexView.isSearchResults);
          gMain.state++;
          break;
      case 3:
          {
              let string: number[] = new Array(64).fill(0);

              StringCopy(string, gText_SizeComparedTo);
              StringAppend(string, gSaveBlock2Ptr.playerName);
              PrintInfoScreenText(string, GetStringCenterAlignXOffset(FONT_NORMAL, string, DISPLAY_WIDTH), 121);
              gMain.state++;
          }
          break;
      case 4:
          ResetPaletteFade();
          gMain.state++;
          break;
      case 5:
          spriteId = CreateSizeScreenTrainerPic(PlayerGenderToFrontTrainerPicId(gSaveBlock2Ptr.playerGender), 152, 56, 0);
          rt.gba.oam[_gs(rt, spriteId).oamIndex].affineMode = ST_OAM_AFFINE_NORMAL;
          rt.gba.oam[_gs(rt, spriteId).oamIndex].affineParamIndex = 1;
          rt.gba.oam[_gs(rt, spriteId).oamIndex].priority = 0;
          _gs(rt, spriteId).y2 = gPokedexEntries[sPokedexListItem.dexNum].trainerOffset;
          SetOamMatrix(rt.gba, 1, gPokedexEntries[sPokedexListItem.dexNum].trainerScale, 0, 0, gPokedexEntries[sPokedexListItem.dexNum].trainerScale);
          LoadPalette(sSizeScreenSilhouette_Pal, OBJ_PLTT_ID2(rt.gba.oam[_gs(rt, spriteId).oamIndex].paletteBank), PLTT_SIZE_4BPP);
          task.data[5] = spriteId;
          gMain.state++;
          break;
      case 6:
          spriteId = CreateMonSpriteFromNationalDexNumber(sPokedexListItem.dexNum, 88, 56, 1);
          rt.gba.oam[_gs(rt, spriteId).oamIndex].affineMode = ST_OAM_AFFINE_NORMAL;
          rt.gba.oam[_gs(rt, spriteId).oamIndex].affineParamIndex = 2;
          rt.gba.oam[_gs(rt, spriteId).oamIndex].priority = 0;
          _gs(rt, spriteId).y2 = gPokedexEntries[sPokedexListItem.dexNum].pokemonOffset;
          SetOamMatrix(rt.gba, 2, gPokedexEntries[sPokedexListItem.dexNum].pokemonScale, 0, 0, gPokedexEntries[sPokedexListItem.dexNum].pokemonScale);
          LoadPalette(sSizeScreenSilhouette_Pal, OBJ_PLTT_ID2(rt.gba.oam[_gs(rt, spriteId).oamIndex].paletteBank), PLTT_SIZE_4BPP);
          task.data[3] = spriteId;
          CopyWindowToVram(WIN_INFO, COPYWIN_FULL);
          CopyBgTilemapBufferToVram(1);
          CopyBgTilemapBufferToVram(2);
          CopyBgTilemapBufferToVram(3);
          gMain.state++;
          break;
      case 7:
          rt.BeginNormalPaletteFade("PALETTES_ALL & ~(0x14)", 0, 0x10, 0, "RGB_BLACK");
          /* noop SetVBlankCallback */;
          gMain.state++;
          break;
      case 8:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          HideBg(0);
          ShowBg(1);
          ShowBg(2);
          ShowBg(3);
          gMain.state++;
          break;
      case 9:
          if (!rt.gPaletteFade.active)
          {
              sPokedexView.screenSwitchState = 0;
              gMain.state = 0;
              task.func = (t) => Task_HandleSizeScreenInput(t, rt);
          }
          break;
      }
};

/** Source: pokedex.c → Task_HandleSizeScreenInput */
