/** Source: pokedex.c → Task_DisplayCaughtMonDexPage */
export const Task_DisplayCaughtMonDexPage: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let spriteId = 0;
      let dexNum = task.data[1];

      switch (task.data[0])
      {
      case 0:
      default:
          if (!rt.gPaletteFade.active)
          {
              gPokedexVBlankCB = gMain.vblankCallback;
              /* noop SetVBlankCallback */;
              ResetOtherVideoRegisters(DISPCNT_BG0_ON);
              ResetBgsAndClearDma3BusyFlags(0);
              InitBgsFromTemplates(0, sNewEntryInfoScreen_BgTemplate, ((sNewEntryInfoScreen_BgTemplate)?.length ?? 0));
              SetBgTilemapBuffer(3, AllocZeroed(BG_SCREEN_SIZE));
              SetBgTilemapBuffer(2, AllocZeroed(BG_SCREEN_SIZE));
              InitWindows(sNewEntryInfoScreen_WindowTemplates);
              DeactivateAllTextPrinters();
              task.data[0] = 1;
          }
          break;
      case 1:
          DecompressAndLoadBgGfxUsingHeap(3, gPokedexMenu_Gfx, 0x2000, 0, 0);
          CopyToBgTilemapBuffer(3, gPokedexInfoScreen_Tilemap, 0, 0);
          FillWindowPixelBuffer(WIN_INFO, PIXEL_FILL(0));
          PutWindowTilemap(WIN_INFO);
          PutWindowTilemap(WIN_FOOTPRINT);
          DrawFootprint(WIN_FOOTPRINT, task.data[1]);
          CopyWindowToVram(WIN_FOOTPRINT, COPYWIN_GFX);
          ResetPaletteFade();
          LoadPokedexBgPalette(false);
          task.data[0]++;
          break;
      case 2:
          task.data[0]++;
          break;
      case 3:
          PrintMonInfo(dexNum, IsNationalPokedexEnabled(), 1, 1);
          CopyWindowToVram(WIN_INFO, COPYWIN_FULL);
          CopyBgTilemapBufferToVram(2);
          CopyBgTilemapBufferToVram(3);
          task.data[0]++;
          break;
      case 4:
          spriteId = CreateMonSpriteFromNationalDexNumber(dexNum, MON_PAGE_X, MON_PAGE_Y, 0);
          rt.gba.oam[_gs(rt, spriteId).oamIndex].priority = 0;
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");
          /* noop SetVBlankCallback */;
          task.data[3] = spriteId;
          task.data[0]++;
          break;
      case 5:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          ShowBg(2);
          ShowBg(3);
          task.data[0]++;
          break;
      case 6:
          if (!rt.gPaletteFade.active)
          {
              PlayCry_Normal(NationalPokedexNumToSpecies(dexNum), 0);
              task.data[2] = 0;
              task.func = (t) => Task_HandleCaughtMonPageInput(t, rt);
          }
          break;
      }
};

/** Source: pokedex.c → Task_HandleCaughtMonPageInput */
export const Task_HandleCaughtMonPageInput: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (JOY_NEW(A_BUTTON | B_BUTTON))
      {
          rt.BeginNormalPaletteFade("PALETTES_BG", 0, 0, 16, "RGB_BLACK");
          rt.setSpriteCallback(task.data[3], SpriteCB_SlideCaughtMonToCenter);
          task.func = (t) => Task_ExitCaughtMonPage(t, rt);
      }
       
      else if (++task.data[2] & 16)
      {
          LoadPalette(gPokedexBgHoenn_Pal + 1, BG_PLTT_ID(3) + 1, PLTT_SIZEOF(7));
      }
      else
      {
          LoadPalette(gPokedexBgHoenn_Pal + 49, BG_PLTT_ID(3) + 1, PLTT_SIZEOF(7));
      }
};

/** Source: pokedex.c → Task_ExitCaughtMonPage */
export const Task_ExitCaughtMonPage: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (!rt.gPaletteFade.active)
      {
          let species = 0;
          let otId = 0;
          let personality = 0;
          let paletteNum = 0;
          let lzPaletteData: any = null;
          let buffer: any = null;

          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          FreeAllWindowBuffers();
          buffer = GetBgTilemapBuffer(2);
          if (buffer)
              Free(buffer);
          buffer = GetBgTilemapBuffer(3);
          if (buffer)
              Free(buffer);

          species = NationalPokedexNumToSpecies(task.data[1]);
          otId = (task.data[13] << 16) | task.data[12];
          personality = (task.data[15] << 16) | task.data[14];
          paletteNum = rt.gba.oam[_gs(rt, task.data[3]).oamIndex].paletteNum;
          lzPaletteData = GetMonSpritePalFromSpeciesAndPersonality(species, otId, personality);
          LoadCompressedPalette(lzPaletteData, OBJ_PLTT_ID(paletteNum), PLTT_SIZE_4BPP);
          rt.DestroyTask(taskId);
      }
};

/** Source: pokedex.c → Task_LoadSearchMenu */
export const Task_LoadSearchMenu: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let i = 0;

      switch (gMain.state)
      {
      default:
      case 0:
          if (!rt.gPaletteFade.active)
          {
              sPokedexView.currentPage = PAGE_SEARCH;
              ResetOtherVideoRegisters(0);
              ResetBgsAndClearDma3BusyFlags(0);
              InitBgsFromTemplates(0, sSearchMenu_BgTemplate, ((sSearchMenu_BgTemplate)?.length ?? 0));
              SetBgTilemapBuffer(3, AllocZeroed(BG_SCREEN_SIZE));
              SetBgTilemapBuffer(2, AllocZeroed(BG_SCREEN_SIZE));
              SetBgTilemapBuffer(1, AllocZeroed(BG_SCREEN_SIZE));
              SetBgTilemapBuffer(0, AllocZeroed(BG_SCREEN_SIZE));
              InitWindows(sSearchMenu_WindowTemplate);
              DeactivateAllTextPrinters();
              PutWindowTilemap(0);
              DecompressAndLoadBgGfxUsingHeap(3, gPokedexSearchMenu_Gfx, 0x2000, 0, 0);

              if (!IsNationalPokedexEnabled())
                  CopyToBgTilemapBuffer(3, gPokedexSearchMenuHoenn_Tilemap, 0, 0);
              else
                  CopyToBgTilemapBuffer(3, gPokedexSearchMenuNational_Tilemap, 0, 0);
              LoadPalette(gPokedexSearchMenu_Pal + 1, BG_PLTT_ID(0) + 1, PLTT_SIZEOF(4 * 16 - 1));
              gMain.state = 1;
          }
          break;
      case 1:
          /* TODO LoadCompressedSpriteSheet — load via rt.LoadCompressedSpriteSheetsFromTable */;
          /* TODO LoadSpritePalettes — load via rt.LoadSpritePalettesFromTable */;
          CreateSearchParameterScrollArrows(taskId);
          for (i = 0; i < NUM_TASK_DATA; i++)
              task.data[i] = 0;
          SetDefaultSearchModeAndOrder(taskId);
          HighlightSelectedSearchTopBarItem(SEARCH_TOPBAR_SEARCH);
          PrintSelectedSearchParameters(taskId);
          CopyWindowToVram(0, COPYWIN_FULL);
          CopyBgTilemapBufferToVram(1);
          CopyBgTilemapBufferToVram(2);
          CopyBgTilemapBufferToVram(3);
          gMain.state++;
          break;
      case 2:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 16, 0, "RGB_BLACK");
          gMain.state++;
          break;
      case 3:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          HideBg(0);
          ShowBg(1);
          ShowBg(2);
          ShowBg(3);
          gMain.state++;
          break;
      case 4:
          if (!rt.gPaletteFade.active)
          {
              task.func = (t) => Task_SwitchToSearchMenuTopBar(t, rt);
              gMain.state = 0;
          }
          break;
      }
};

