/** Source: pokedex.c → Task_HandleSearchParameterInput */
export const Task_HandleSearchParameterInput: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let menuItem = 0;
      let texts: any = null;
      let cursorPos = 0;
      let scrollOffset = 0;
      let maxOption = 0;
      let moved = 0;

      menuItem = task.data[1];
      texts = sSearchOptions[menuItem].texts;
      cursorPos = task.data[sSearchOptions[menuItem].taskDataCursorPos];
      scrollOffset = task.data[sSearchOptions[menuItem].taskDataScrollOffset];
      maxOption = sSearchOptions[menuItem].numOptions - 1;
      if (JOY_NEW(A_BUTTON))
      {
          /* TODO sound PlaySE */;
          ClearSearchParameterBoxText();
          DrawOrEraseSearchParameterBox(true);
          task.func = (t) => Task_SwitchToSearchMenu(t, rt);
          CopyWindowToVram(0, COPYWIN_GFX);
          CopyBgTilemapBufferToVram(3);
          return;
      }
      if (JOY_NEW(B_BUTTON))
      {
          /* TODO sound PlaySE */;
          ClearSearchParameterBoxText();
          DrawOrEraseSearchParameterBox(true);
          cursorPos = task.data[14];
          scrollOffset = task.data[15];
          task.func = (t) => Task_SwitchToSearchMenu(t, rt);
          CopyWindowToVram(0, COPYWIN_GFX);
          CopyBgTilemapBufferToVram(3);
          return;
      }
      moved = false;
      if (JOY_REPEAT(DPAD_UP))
      {
          if (cursorPos != 0)
          {
               
              EraseSelectorArrow(cursorPos);
              (cursorPos)--;
              PrintSelectorArrow(cursorPos);
              moved = true;
          }
          else if (scrollOffset != 0)
          {
               
              (scrollOffset)--;
              PrintSearchParameterText(taskId);
              PrintSelectorArrow(cursorPos);
              moved = true;
          }
          if (moved)
          {
              /* TODO sound PlaySE */;
              EraseAndPrintSearchTextBox(texts[cursorPos + scrollOffset].description);
              CopyWindowToVram(0, COPYWIN_GFX);
          }
          return;
      }
      if (JOY_REPEAT(DPAD_DOWN))
      {
          if (cursorPos < MAX_SEARCH_PARAM_CURSOR_POS && cursorPos < maxOption)
          {
               
              EraseSelectorArrow(cursorPos);
              (cursorPos)++;
              PrintSelectorArrow(cursorPos);
              moved = true;
          }
          else if (maxOption > MAX_SEARCH_PARAM_CURSOR_POS && scrollOffset < maxOption - MAX_SEARCH_PARAM_CURSOR_POS)
          {
               
              (scrollOffset)++;
              PrintSearchParameterText(taskId);
              PrintSelectorArrow(5);
              moved = true;
          }
          if (moved)
          {
              /* TODO sound PlaySE */;
              EraseAndPrintSearchTextBox(texts[cursorPos + scrollOffset].description);
              CopyWindowToVram(0, COPYWIN_GFX);
          }
          return;
      }
};

