/** Source: pokedex.c → CB2_OpenPokedex */
export const CB2_OpenPokedex: CB2Callback = (rt) => {
  switch (gMain.state)
      {
      case 0:
      default:
          /* noop SetVBlankCallback */;
          ResetOtherVideoRegisters(0);
          DmaFillLarge16(3, 0, VRAM, VRAM_SIZE, 0x1000);
          DmaClear32(3, OAM, OAM_SIZE);
          /* TODO DmaClear16 (memory clear) */;
          gMain.state = 1;
          break;
      case 1:
          ScanlineEffect_Stop();
          ResetTasks();
          rt.ResetSpriteData();
          ResetPaletteFade();
          /* TODO FreeAllSpritePalettes */;
          gReservedSpritePaletteCount = 8;
          ResetAllPicSprites();
          gMain.state++;
          break;
      case 2:
          sPokedexView = AllocZeroed(/* ((struct)?.length ?? 32) */ 0);
          ResetPokedexView(sPokedexView);
          rt.CreateTask((t) => Task_OpenPokedexMainPage(t, rt), 0);
          sPokedexView.dexMode = gSaveBlock2Ptr.pokedex.mode;
          if (!IsNationalPokedexEnabled())
              sPokedexView.dexMode = DEX_MODE_HOENN;
          sPokedexView.dexOrder = gSaveBlock2Ptr.pokedex.order;
          sPokedexView.selectedPokemon = sLastSelectedPokemon;
          sPokedexView.pokeBallRotation = sPokeBallRotation;
          sPokedexView.selectedScreen = AREA_SCREEN;
          if (!IsNationalPokedexEnabled())
          {
              sPokedexView.seenCount = GetHoennPokedexCount(FLAG_GET_SEEN);
              sPokedexView.ownCount = GetHoennPokedexCount(FLAG_GET_CAUGHT);
          }
          else
          {
              sPokedexView.seenCount = GetNationalPokedexCount(FLAG_GET_SEEN);
              sPokedexView.ownCount = GetNationalPokedexCount(FLAG_GET_CAUGHT);
          }
          sPokedexView.initialVOffset = 8;
          gMain.state++;
          break;
      case 3:
          EnableInterrupts(1);
          /* noop SetVBlankCallback */;
          /* TODO scene transition: SetMainCallback2(CB2_Pokedex) */;
          CreatePokedexList(sPokedexView.dexMode, sPokedexView.dexOrder);
          m4aMPlayVolumeControl(gMPlayInfo_BGM, TRACKS_ALL, 0x80);
          break;
      }
};

/** Source: pokedex.c → CB2_Pokedex */
export const CB2_Pokedex: CB2Callback = (rt) => {
  RunTasks();
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
};
